package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5/pgxpool"
)

const operation = "bulk-approve.v3"

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		hash := requestHash(ids)
		response, err := json.Marshal(protocol.Result{ApprovedIDs: ids})
		if err != nil {
			return protocol.Result{}, false, err
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		// These settings are transaction-local and are the identity used by every
		// RLS policy in the action transaction.
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// The unique scope row is also the serialization point for concurrent
		// requests using the same key. A rolled-back transaction does not reserve it.
		_, err = tx.Exec(ctx, `
			INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response)
			VALUES ($1,$2,$3,$4,$5,$6::jsonb)
			ON CONFLICT ("tenantId","actorId",operation,key) DO NOTHING`,
			u.Tenant, u.User, operation, key, hash, response)
		if err != nil {
			return protocol.Result{}, false, err
		}

		var storedHash string
		var storedResponse []byte
		err = tx.QueryRow(ctx, `
			SELECT "requestHash", response
			FROM "ActionRequest"
			WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4
			FOR UPDATE`, u.Tenant, u.User, operation, key).Scan(&storedHash, &storedResponse)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if storedHash != hash {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}
		// An existing completed row is an idempotent replay. The row is always
		// completed before commit because it is inserted in this same transaction.
		if string(storedResponse) != string(response) {
			var replay protocol.Result
			if err = json.Unmarshal(storedResponse, &replay); err != nil {
				return protocol.Result{}, false, err
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return replay, true, nil
		}
		// A matching response means either this request inserted the row or a
		// prior request completed it. Distinguish those cases by checking whether
		// the target rows are still submitted below; prior completion replays.
		// Since response is deterministic, a matching existing row is sufficient
		// to replay only when its targets are already approved by this operation.
		var auditCount int
		err = tx.QueryRow(ctx, `SELECT count(*) FROM "ApprovalAudit" WHERE "tenantId"=$1 AND "approvedBy"=$2 AND operation=$3 AND "idempotencyKey"=$4`, u.Tenant, u.User, operation, key).Scan(&auditCount)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if auditCount == len(ids) {
			var replay protocol.Result
			if err = json.Unmarshal(storedResponse, &replay); err != nil {
				return protocol.Result{}, false, err
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return replay, true, nil
		}

		// Lock every requested target in canonical order. RLS limits this query to
		// the authenticated tenant and the approval policy limits it to valid
		// submitted targets created by somebody else.
		rows, err := tx.Query(ctx, `
			SELECT id
			FROM "Purchase"
			WHERE id=ANY($1::text[])
			  AND "tenantId"=$2
			  AND "createdBy"<>$3
			  AND status='submitted'
			ORDER BY id
			FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := make([]string, 0, len(ids))
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		tag, err := tx.Exec(ctx, `
			UPDATE "Purchase"
			SET status='approved'
			WHERE id=ANY($1::text[])
			  AND "tenantId"=$2
			  AND "createdBy"<>$3
			  AND status='submitted'`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		for _, id := range ids {
			_, err = tx.Exec(ctx, `
				INSERT INTO "ApprovalAudit" ("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus")
				VALUES ($1,$2,$3,$4,$5,'submitted','approved')`,
				u.Tenant, id, u.User, operation, key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return protocol.Result{ApprovedIDs: ids}, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

func requestHash(ids []string) string {
	ordered := append([]string(nil), ids...)
	sort.Strings(ordered)
	h := sha256.New()
	_, _ = h.Write([]byte(operation + "\n"))
	for _, id := range ordered {
		_, _ = fmt.Fprintf(h, "%d:%s", len([]byte(id)), id)
	}
	return hex.EncodeToString(h.Sum(nil))
}

